import{b as e,O as o,g as d,j as a}from"./chunks/framework.DSt9LnBW.js";const b=JSON.parse('{"title":"Web 界面怎么用","description":"","frontmatter":{},"headers":[],"relativePath":"performance/locust/intro/web-ui/index.md","filePath":"性能测试/2.Locust/1.入门篇/04.Web界面怎么用.md","lastUpdated":1789911840000}'),r={name:"performance/locust/intro/web-ui/index.md"};function s(n,t,c,i,l,h){return o(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="web-界面怎么用" tabindex="-1">Web 界面怎么用 <a class="header-anchor" href="#web-界面怎么用" aria-label="Permalink to &quot;Web 界面怎么用&quot;">​</a></h1><blockquote><p>把 Locust 的 Web 界面逐个区域讲清楚：加压怎么调、图表怎么看、报错去哪查、数据怎么导出来。</p></blockquote><h2 id="界面从哪来" tabindex="-1">界面从哪来 <a class="header-anchor" href="#界面从哪来" aria-label="Permalink to &quot;界面从哪来&quot;">​</a></h2><p>启动时不加 <code>--headless</code>，Locust 就会开一个 Web 服务：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">locust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locustfile.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host=http://localhost:3001</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → Starting web interface at http://0.0.0.0:8089</span></span></code></pre></div><p>浏览器打开 <a href="http://localhost:8089" target="_blank" rel="noreferrer">http://localhost:8089</a>。</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>--web-host 127.0.0.1</code></td><td>只允许本机访问（默认 <code>*</code> 所有网卡）</td></tr><tr><td><code>--web-port 8090</code> / <code>-P 8090</code></td><td>换端口（默认 8089）</td></tr></tbody></table><blockquote><p>默认监听所有网卡，<strong>别把 8089 暴露到公网</strong>——这个界面能直接对目标发起压测。</p></blockquote><h2 id="起始页-三个输入框" tabindex="-1">起始页：三个输入框 <a class="header-anchor" href="#起始页-三个输入框" aria-label="Permalink to &quot;起始页：三个输入框&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输入框</th><th>说明</th><th>怎么填</th></tr></thead><tbody><tr><td><strong>Number of users</strong></td><td>峰值并发用户数</td><td>先小后大，10 → 50 → 200</td></tr><tr><td><strong>Spawn rate</strong></td><td>每秒启动几个用户</td><td>中低负载填 <code>用户数 ÷ 10</code> 左右，别一步到位</td></tr><tr><td><strong>Host</strong></td><td>被测服务地址</td><td>命令行给了 <code>--host</code> 就自动填好</td></tr></tbody></table><p>点 <strong>Start swarming</strong> 开始。三个值随时能改，见下面&quot;压测中的动态调整&quot;。</p><h2 id="顶部菜单-压测过程中能做什么" tabindex="-1">顶部菜单：压测过程中能做什么 <a class="header-anchor" href="#顶部菜单-压测过程中能做什么" aria-label="Permalink to &quot;顶部菜单：压测过程中能做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按钮</th><th>作用</th></tr></thead><tbody><tr><td><strong>Stop</strong></td><td>停止本次压测（数据保留在界面上）</td></tr><tr><td><strong>Edit</strong> / <code>+</code> <code>-</code></td><td>压测中调整用户数——<strong>找拐点最常用的操作</strong></td></tr><tr><td><strong>New test</strong></td><td>清空统计，重新开始一次压测</td></tr><tr><td><strong>Download Data</strong></td><td>导出 CSV，见下文</td></tr><tr><td><strong>Charts / Statistics / Failures / Exceptions / Tasks / Logs</strong></td><td>切换不同视图</td></tr></tbody></table><p><strong>动态调整是重点</strong>：不用停下脚本就能从 10 个用户一点一点加到 100，观察 RPS 在哪一档开始不涨了。这比&quot;配好一堆档位跑好几轮&quot;高效得多。</p><h2 id="statistics-主统计表" tabindex="-1">Statistics：主统计表 <a class="header-anchor" href="#statistics-主统计表" aria-label="Permalink to &quot;Statistics：主统计表&quot;">​</a></h2><p>一个「<strong>请求方法 + 请求名</strong>」一行，列的含义：</p><table tabindex="0"><thead><tr><th>列</th><th>含义</th><th>关注点</th></tr></thead><tbody><tr><td><code>Type</code></td><td>请求方法</td><td>GET / POST</td></tr><tr><td><code>Name</code></td><td>请求名</td><td>默认是路径；用 <code>name=</code> 可以自定义（第 10 章<a href="/performance/locust/core/request-grouping/">让报告别爆炸</a>）</td></tr><tr><td><code># reqs</code></td><td>总请求数</td><td>样本量太小别急着下结论</td></tr><tr><td><code># fails</code></td><td>失败数（比例）</td><td><strong>先看这里，不是 0 就先排查</strong></td></tr><tr><td><code>Median</code> / <code>Avg</code></td><td>中位数 / 平均值</td><td>平均值会被极端值拉偏</td></tr><tr><td><code>Min</code> / <code>Max</code></td><td>最快 / 最慢</td><td>Max 离群说明有卡顿</td></tr><tr><td><code>req/s</code></td><td>每秒请求数（RPS）</td><td>容量指标</td></tr><tr><td><code>failures/s</code></td><td>每秒失败数</td><td>与用户数一起看</td></tr></tbody></table><blockquote><p><strong>判读顺序和 JMeter 一样</strong>：<code># fails</code> → RPS → 高分位响应时间 → 趋势。详细解释见 <a href="/performance/jmeter/metrics/">JMeter 篇·指标解读</a>。</p></blockquote><p>点表头的 <code>Name</code> 之类的列名可以排序；每行左侧能展开看该请求的分位响应时间（P50/P60/…/P99/P100）。</p><h2 id="charts-三条曲线看出瓶颈" tabindex="-1">Charts：三条曲线看出瓶颈 <a class="header-anchor" href="#charts-三条曲线看出瓶颈" aria-label="Permalink to &quot;Charts：三条曲线看出瓶颈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>图表</th><th>看什么</th></tr></thead><tbody><tr><td><strong>Total Requests per Second</strong></td><td>RPS 是否随用户数增长</td></tr><tr><td><strong>Response Times (ms)</strong></td><td>P50 与 P95 的走势，是否抬头上翘</td></tr><tr><td><strong>Number of Users</strong></td><td>用户爬升曲线，与上面两条对齐看</td></tr></tbody></table><p>判断系统是否饱和，就记一句话：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户数还在涨  +  RPS 不再涨  +  响应时间飙升</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>      系统已经饱和，这个点就是瓶颈</span></span></code></pre></div><p>反过来，如果响应时间一直平稳，说明系统还有余力，继续加用户直到找不出拐点为止。</p><blockquote><p>官方文档的原话大意：当用户数加到某个值后，响应时间涨得飞快，即使 Locust 还在加用户，RPS 也不再增加——目标服务&quot;过载&quot;了。</p></blockquote><p><strong>图表有延迟</strong>：Locust 默认每秒刷新一次统计数据，图上看到的是趋势，不是实时精确值。</p><h2 id="failures-与-exceptions-报错去哪查" tabindex="-1">Failures 与 Exceptions：报错去哪查 <a class="header-anchor" href="#failures-与-exceptions-报错去哪查" aria-label="Permalink to &quot;Failures 与 Exceptions：报错去哪查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标签</th><th>内容</th><th>用途</th></tr></thead><tbody><tr><td><strong>Failures</strong></td><td>失败的<strong>请求</strong>，按错误信息聚合（如 <code>401</code>、<code>500</code>、<code>Expected 200 but got 404</code>）</td><td>定位&quot;哪类请求、错在什么原因&quot;</td></tr><tr><td><strong>Exceptions</strong></td><td>用户代码抛出的<strong>异常</strong>（含堆栈）</td><td>定位&quot;脚本写错了&quot;还是&quot;服务真的挂了&quot;</td></tr></tbody></table><p>两个典型场景：</p><table tabindex="0"><thead><tr><th>现象</th><th>大概率原因</th></tr></thead><tbody><tr><td>大量 <code>401 Unauthorized</code></td><td>Token 没带上、或登录失败后没处理</td></tr><tr><td><code>ConnectionError</code> / <code>Max retries exceeded</code></td><td>被测服务端口不对或已经压挂了</td></tr><tr><td>Exceptions 里有 <code>KeyError: &#39;data&#39;</code></td><td>脚本里取响应字段的写法有问题（比如登录失败还硬取 token）</td></tr></tbody></table><blockquote><p>调试习惯：<strong>先让 <code># fails</code> 归零，再谈性能数字。</strong> 带错误的压测结果没有任何参考价值。</p></blockquote><h2 id="download-data-导出结果" tabindex="-1">Download Data：导出结果 <a class="header-anchor" href="#download-data-导出结果" aria-label="Permalink to &quot;Download Data：导出结果&quot;">​</a></h2><p>点 <strong>Download Data</strong> 选项卡，可以下载：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>*_stats.csv</code></td><td>汇总统计（跟界面上一样）</td></tr><tr><td><code>*_stats_history.csv</code></td><td><strong>每秒快照</strong>，用来画趋势图</td></tr><tr><td><code>*_failures.csv</code></td><td>失败明细</td></tr><tr><td><code>*_exceptions.csv</code></td><td>异常明细</td></tr></tbody></table><p>也有直接下载 <strong>HTML 报告</strong> 的入口，可以直接把文件发给同事看。</p><blockquote><p>命令行模式下用 <code>--csv</code> 和 <code>--html</code> 做同样的事，<a href="/performance/locust/intro/cli-and-headless/">下一章</a>细讲。压测时想要&quot;每秒快照&quot;这个粒度，命令行要加 <code>--csv-full-history</code>。</p></blockquote><h2 id="tasks-看看任务分布对不对" tabindex="-1">Tasks：看看任务分布对不对 <a class="header-anchor" href="#tasks-看看任务分布对不对" aria-label="Permalink to &quot;Tasks：看看任务分布对不对&quot;">​</a></h2><p><strong>Tasks</strong> 标签列出每个任务的执行次数。用它验证权重有没有生效：<code>@task(3)</code> 和 <code>@task(1)</code> 跑一段时间后，次数比例应该接近 3:1。</p><p>比例明显不对，通常是任务里有异常被抛出、或者 <code>wait_time</code> 把节奏拖住了。</p><h2 id="logs-运行日志" tabindex="-1">Logs：运行日志 <a class="header-anchor" href="#logs-运行日志" aria-label="Permalink to &quot;Logs：运行日志&quot;">​</a></h2><p><strong>Logs</strong> 标签显示 Locust 进程的运行日志，排查&quot;用户为什么没起来&quot;&quot;worker 有没有连上&quot;这类问题看这里。</p><h2 id="键盘也能操作" tabindex="-1">键盘也能操作 <a class="header-anchor" href="#键盘也能操作" aria-label="Permalink to &quot;键盘也能操作&quot;">​</a></h2><p>在<strong>终端窗口</strong>（不是浏览器）里跑 <code>--headless</code> 时，可以用键盘动态调整：</p><table tabindex="0"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td><code>w</code></td><td>增加 1 个用户</td></tr><tr><td><code>W</code></td><td>增加 10 个用户</td></tr><tr><td><code>s</code></td><td>减少 1 个用户</td></tr><tr><td><code>S</code></td><td>减少 10 个用户</td></tr></tbody></table><blockquote><p>想让终端接收按键，<code>--headless</code> 运行时<strong>别切走</strong>焦点；也可以用 <code>--autostart</code>（立即开始，但仍保留 Web 界面）。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>起始页</strong>：Number of users / Spawn rate / Host，先小后大</li><li><strong>压测中</strong>：用 Edit 或 <code>+</code>/<code>-</code> 动态调整用户数找拐点，比反复重启脚本高效</li><li><strong>Statistics</strong>：先看 <code># fails</code>，再看 RPS 和高分位响应时间</li><li><strong>Charts</strong>：用户数涨、RPS 不涨、响应时间飙升 = 系统饱和</li><li><strong>Failures / Exceptions</strong>：分别对应&quot;请求失败&quot;和&quot;脚本异常&quot;</li><li><strong>Download Data</strong>：导出 CSV 或 HTML 报告存档</li></ul><p>界面顺手了，下一章看怎么脱离界面、在命令行和 CI 里跑 Locust。</p>`,48)])])}const u=e(r,[["render",s]]);export{b as __pageData,u as default};
